from itertools import permutations

def langford_sequence(n, k):
    for p in permutations(range(1, n+1)):
        seq = [0] * (2 * n)
        for i, num in enumerate(p):
            seq[2*i] = num
            seq[2*i + num + 1] = num
        yield seq

n = 8
k = 2
fixed_values = {4: 7, 8: 5, 10: 4}
for seq in langford_sequence(n, k):
    if all(seq[i] == fixed_values[i] for i in fixed_values):
        print(seq)
        break
else:
    print("UNSATISFIABLE")
